#!/usr/bin/env python3
"""Read-only source normalization for the documented synthetic inventory schema."""

import argparse
from collections import Counter
import csv
from datetime import date
import io
import json
from pathlib import Path
import re
import sys


INPUT_COLUMNS = ["record_id", "item", "quantity", "unit_cost", "observed_date", "notes"]
OUTPUT_COLUMNS = ["source_row", "record_id", "item", "quantity", "unit_cost_cents", "observed_date", "notes"]
ASCII_WHITESPACE = " \t\r\n\v\f"
QUANTITY = re.compile(r"[0-9]+")
COST = re.compile(r"[0-9]+(?:\.[0-9]{1,2})?")
DATE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")


class ExportError(Exception):
    """An export could not be produced without guessing or overwriting."""


def reject_symlinks(path):
    if any(part.is_symlink() for part in (path, *path.parents)):
        raise ExportError(f"Symlinked paths are not supported: {path}")


def canonical_digits(value):
    return value.lstrip("0") or "0"


def valid_date(value):
    if DATE.fullmatch(value) is None:
        return False
    try:
        date(int(value[:4]), int(value[5:7]), int(value[8:]))
    except ValueError:
        return False
    return True


def read_records(source):
    # csv defaults to a small field limit; do not silently reject ordinary long notes.
    limit = sys.maxsize
    while True:
        try:
            csv.field_size_limit(limit)
            break
        except OverflowError:
            limit //= 10
    records = []
    with source.open("r", encoding="utf-8-sig", newline="") as stream:
        reader = csv.reader(stream, strict=True)
        header = next(reader, None)
        if header != INPUT_COLUMNS:
            raise ExportError(f"Unexpected schema. Expected {INPUT_COLUMNS!r}; found {header!r}.")
        for source_row, cells in enumerate(reader, 1):
            if len(cells) != len(INPUT_COLUMNS):
                raise ExportError(f"CSV record {source_row} has {len(cells)} fields; expected 6. No records were exported.")
            records.append(cells)
    return records


def normalize(records):
    issues = []
    normalized = []
    id_counts = Counter(row[0] for row in records if row[0] != "")
    invalid_cells = 0
    duplicate_id_rows = 0

    def issue(source_row, field, code, raw):
        issues.append({"source_row": source_row, "field": field, "code": code, "raw_value": raw})

    for source_row, cells in enumerate(records, 1):
        record_id, item, quantity_raw, cost_raw, date_raw, notes = cells
        if record_id == "":
            issue(source_row, "record_id", "missing", record_id)
            invalid_cells += 1
        elif id_counts[record_id] > 1:
            issue(source_row, "record_id", "duplicate_id", record_id)
            duplicate_id_rows += 1

        quantity = quantity_raw.strip(ASCII_WHITESPACE)
        if QUANTITY.fullmatch(quantity) is None:
            quantity = ""
            issue(source_row, "quantity", "invalid", quantity_raw)
            invalid_cells += 1
        else:
            quantity = canonical_digits(quantity)

        cost = cost_raw.strip(ASCII_WHITESPACE)
        if COST.fullmatch(cost) is None:
            cents = ""
            issue(source_row, "unit_cost", "invalid", cost_raw)
            invalid_cells += 1
        else:
            dollars, separator, fraction = cost.partition(".")
            cents = canonical_digits(dollars + fraction.ljust(2, "0"))

        if valid_date(date_raw):
            observed_date = date_raw
        else:
            observed_date = ""
            issue(source_row, "observed_date", "invalid", date_raw)
            invalid_cells += 1

        normalized.append([source_row, record_id, item.strip(ASCII_WHITESPACE), quantity, cents, observed_date, notes])

    summary = {"input_rows": len(records), "output_rows": len(normalized),
               "invalid_cells": invalid_cells, "duplicate_id_rows": duplicate_id_rows}
    return normalized, issues, summary


def render(normalized, issues, summary):
    buffer = io.StringIO(newline="")
    writer = csv.writer(buffer, lineterminator="\n")
    writer.writerow(OUTPUT_COLUMNS)
    writer.writerows(normalized)
    return {"normalized.csv": buffer.getvalue(),
            "issues.json": json.dumps(issues, ensure_ascii=False, indent=2, allow_nan=False) + "\n",
            "summary.json": json.dumps(summary, ensure_ascii=False, indent=2, allow_nan=False) + "\n"}


def export(source, destination):
    source = source.absolute()
    destination = destination.absolute()
    reject_symlinks(source)
    reject_symlinks(destination)
    if not source.is_file():
        raise ExportError(f"Input is not a regular file: {source}")
    if destination.exists():
        raise ExportError(f"Output directory already exists; choose a fresh export directory: {destination}")
    if not destination.parent.is_dir():
        raise ExportError(f"Output parent directory does not exist: {destination.parent}")

    records = read_records(source)
    normalized, issues, summary = normalize(records)
    contents = render(normalized, issues, summary)
    # Validate and render everything before creating any result. Exclusive creation
    # protects earlier exports; ordinary write failures clean up only our own files.
    reject_symlinks(destination)
    destination.mkdir(exist_ok=False)
    created = []
    try:
        for name, text in contents.items():
            path = destination / name
            with path.open("x", encoding="utf-8", newline="") as stream:
                created.append(path)
                stream.write(text)
    except BaseException:
        for path in created:
            try:
                path.unlink()
            except OSError:
                pass
        try:
            destination.rmdir()
        except OSError:
            pass
        raise
    return summary


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--input", required=True, type=Path)
    parser.add_argument("--output-dir", default=Path("output"), type=Path)
    args = parser.parse_args()
    try:
        summary = export(args.input, args.output_dir)
    except (ExportError, OSError, UnicodeError, csv.Error, MemoryError) as error:
        print(f"ERROR: {error}", file=sys.stderr)
        return 2
    print(json.dumps(summary, sort_keys=True))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
